void test_file_to_ximage_has_no_decoder_and_returns_null(void) {
  TEST_ASSERT_NULL(file_to_ximage(dpy, NULL, "/no/such/mask.png"));
}

void test_ease_in_out_sine_runs_from_0_to_1_through_one_half(void) {
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.0, ease(EASE_IN_OUT_SINE, 0.0));
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.5, ease(EASE_IN_OUT_SINE, 0.5));
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 1.0, ease(EASE_IN_OUT_SINE, 1.0));
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.146447, ease(EASE_IN_OUT_SINE, 0.25));
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.853553, ease(EASE_IN_OUT_SINE, 0.75));
}

void test_ease_in_out_sine_does_not_clamp_past_the_end(void) {
  /* unknownpleasures passes height * 1.5; upstream does not clamp, so 1.5
   * lands on 0.5 and the shim must match. */
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.5, ease(EASE_IN_OUT_SINE, 1.5));
}

void test_ease_in_sine_and_out_sine_are_the_two_halves(void) {
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.0, ease(EASE_IN_SINE, 0.0));
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 1.0, ease(EASE_IN_SINE, 1.0));
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.292893, ease(EASE_IN_SINE, 0.5));
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.0, ease(EASE_OUT_SINE, 0.0));
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 1.0, ease(EASE_OUT_SINE, 1.0));
  TEST_ASSERT_DOUBLE_WITHIN(1e-6, 0.707107, ease(EASE_OUT_SINE, 0.5));
}

void test_ease_none_returns_its_input(void) {
  TEST_ASSERT_EQUAL_DOUBLE(0.3, ease(EASE_NONE, 0.3));
  TEST_ASSERT_EQUAL_DOUBLE(7.0, ease(EASE_NONE, 7.0));
}

void test_double_time_is_wall_clock_seconds_and_moves_forward(void) {
  double a = double_time();
  usleep(20000);
  double b = double_time();
  TEST_ASSERT_TRUE_MESSAGE(a > 1e9, "not seconds since the epoch");
  TEST_ASSERT_TRUE_MESSAGE(b - a >= 0.015, "did not advance by the sleep");
  TEST_ASSERT_TRUE_MESSAGE(b - a < 1.0, "advanced by far more than the sleep");
}

